head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//전일 채권 표준코드부여종목중 정보문의 미전송종목 조회
scwin.vScrenID = "ULDINS93100.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 전일 채권 표준코드부여종목중 정보문의 미전송종목 조회
 ***********************************************/
scwin.ins_search = function() {
    var queryId = "";
    // 전일 채권 표준코드부여종목중 정보문의 미전송종목 조회
    // param1 => 표준코드 STD_CD 
    queryId = "lds.ins.common.select.listUnTrsBndCdInquiry";
    //alert(queryId); 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS93100_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId;
    // "&{P}param01=" + txb_pSTD_CD.value ;

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
    scwin.arrPar[2] = txb_param3.getValue();
};
scwin.gform_onload = function() {
    scwin.ins_search();
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(txb_param3, false);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    if (rowcount == 0) {
        await $c.frame.CloseFrame();
    }
    //alert('dts_List.OnLoadCompleted('+rowcount+')');

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (row == 0) return;
    txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    txb_param2.setValue(dts_List.getCellData(row, "ISU_NM"));
    txb_param3.setValue(dts_List.getCellData(row, "TRNSM_DD"));
    fn_GetPar = fn_GetParam;
    await $c.frame.CreateDialogFrame("ULDINS30700", "/search/ULDINS30700.gfm", "채권발행정보 정보문의전송조회_INS30700", 0, 0, 1300, 780, "tool");
};
